<template>
  <div class="mine-page">
    <header class="page-head"><div><span>MARKET CENTER</span><h1>我的商城</h1><p>管理商品、购买意向、平台订单、评价和卖家结算资料。</p></div><div><el-button @click="$router.push({name:'market-messages'})">交易消息 {{ data.conversationCount||'' }}</el-button><el-button type="primary" @click="$router.push({name:'market-publish'})">发布商品</el-button></div></header>
    <el-tabs v-model="tab" class="market-tabs cpu-card" v-loading="loading" @tab-change="syncTab">
      <el-tab-pane label="我发布的" name="selling">
        <div class="section-tools"><el-segmented v-model="sellingStatus" :options="sellingOptions" /><span>{{ filteredSelling.length }} 件</span></div>
        <div v-if="filteredSelling.length" class="listing-list">
          <article v-for="item in filteredSelling" :key="item.id"><div class="item-cover"><img v-if="item.cover" :src="item.cover" :alt="item.title" /><span v-else>📦</span></div><div class="item-main"><div><strong>{{ item.title }}</strong><em>{{ itemStatus(item) }}</em></div><p>{{ item.listingType==='wanted'?'预算 ':'' }}¥{{ item.price }} · {{ item.favoriteCount }} 收藏 · {{ item.offerCount }} 意向</p><small>{{ item.campus||'校区待协商' }} · {{ fmtRelative(item.updatedAt) }}</small></div><div class="item-actions"><el-button size="small" @click="$router.push({name:'market-item',params:{id:item.id}})">查看</el-button><el-button size="small" @click="$router.push({name:'market-edit',params:{id:item.id}})">编辑</el-button></div></article>
        </div><el-empty v-else description="当前没有商品" />
      </el-tab-pane>

      <el-tab-pane label="购买意向" name="offers">
        <div v-if="sellerOffers.length" class="offer-list"><article v-for="offer in sellerOffers" :key="offer.id"><div><strong>{{ offer.item?.title }}</strong><p>{{ offer.buyer?.nickname||`用户 #${offer.buyer?.id}` }} 出价 <b>¥{{ offer.price }}</b></p><small>{{ offer.message||'未留言' }}</small></div><div><el-button size="small" @click="$router.push({name:'market-messages',query:{conversation:offer.conversationId}})">沟通</el-button><el-button size="small" type="danger" plain :loading="actingId===offer.id" @click="handleOffer(offer,'reject')">拒绝</el-button><el-button size="small" type="primary" :loading="actingId===offer.id" @click="handleOffer(offer,'accept')">接受并待支付</el-button></div></article></div>
        <div v-if="buyerOffers.length" class="offer-list"><h3>我提交的</h3><article v-for="offer in buyerOffers" :key="offer.id"><div><strong>{{ offer.item?.title }}</strong><p>出价 <b>¥{{ offer.price }}</b> · {{ offerStatus(offer.status) }}</p><small>{{ offer.message||'未留言' }}</small></div><div><el-button size="small" @click="$router.push({name:'market-item',params:{id:offer.itemId}})">查看商品</el-button><el-button v-if="offer.status==='pending'" size="small" @click="handleOffer(offer,'cancel')">撤回</el-button></div></article></div>
        <el-empty v-if="!sellerOffers.length&&!buyerOffers.length" description="暂无购买意向" />
      </el-tab-pane>

      <el-tab-pane label="平台订单" name="orders">
        <div class="order-list" v-if="data.orders.length"><article v-for="order in data.orders" :key="order.id" class="order-card"><header><span>订单 {{ order.outTradeNo }}</span><em>{{ orderStatus(order.status) }}</em></header><div class="order-body"><div class="item-cover"><img v-if="order.item?.images?.[0]?.url" :src="order.item.images[0].url" :alt="order.item.title" /><span v-else>{{ order.deliveryType==='digital'?'📁':'📦' }}</span></div><div class="order-copy"><strong>{{ order.item?.title }}</strong><p>实付金额 <b>¥{{ order.amount }}</b></p><small>{{ order.buyerId===auth.user?.id?'卖家':'买家' }}：{{ order.buyerId===auth.user?.id?(order.seller?.nickname||`用户 #${order.seller?.id}`):(order.buyer?.nickname||`用户 #${order.buyer?.id}`) }}</small><small v-if="order.deliveryType==='digital'">线上发货{{ order.digitalDeliveredAt ? ` · ${formatTime(order.digitalDeliveredAt)}` : '' }}</small><small v-else-if="order.meetupLocation">交付：{{ order.meetupLocation }} {{ order.meetupTime?formatTime(order.meetupTime):'' }}</small></div></div><div v-if="order.deliveryType==='digital'&&order.digitalDelivery" class="digital-delivery"><b>📁 电子资料交付内容</b><pre>{{ order.digitalDelivery }}</pre><small>仅订单双方可见，请勿转发或泄露下载凭证。</small></div><footer>
            <el-button size="small" @click="$router.push({name:'market-messages',query:{item:order.itemId}})">交易沟通</el-button>
            <el-button v-if="order.status==='pending_payment'&&order.buyerId===auth.user?.id" size="small" type="primary" @click="openPay(order)">立即支付</el-button>
            <el-button v-if="order.deliveryType!=='digital'&&['paid','delivering'].includes(order.status)" size="small" @click="openMeetup(order)">交付安排</el-button>
            <el-button v-if="['paid','delivering'].includes(order.status)&&order.buyerId===auth.user?.id&&!order.buyerConfirmedAt" size="small" type="success" @click="orderAction(order,'buyer_confirm')">买家确认收到</el-button>
            <el-button v-if="['paid','delivering'].includes(order.status)&&order.sellerId===auth.user?.id&&!order.sellerConfirmedAt" size="small" type="success" @click="orderAction(order,'seller_confirm')">卖家确认交付</el-button>
            <el-button v-if="['paid','delivering'].includes(order.status)&&order.buyerId===auth.user?.id" size="small" type="danger" plain @click="openRefund(order)">申请退款</el-button>
            <el-button v-if="order.status==='completed'&&!hasReviewed(order)" size="small" @click="openReview(order)">评价交易</el-button>
          </footer></article></div><el-empty v-else description="暂无平台订单" />
      </el-tab-pane>

      <el-tab-pane label="我的收藏" name="favorites"><div v-if="data.favorites.length" class="favorite-grid"><article v-for="item in data.favorites" :key="item.id" @click="$router.push({name:'market-item',params:{id:item.id}})"><div><img v-if="item.cover" :src="item.cover" :alt="item.title" /><span v-else>📦</span></div><strong>{{ item.title }}</strong><b>¥{{ item.price }}</b></article></div><el-empty v-else description="还没有收藏商品" /></el-tab-pane>
      <el-tab-pane label="收款与结算" name="payout"><div class="payout-card"><h2>卖家收款资料</h2><p>交易完成后平台生成结算单。收款账号使用服务器密钥加密保存，页面只显示掩码。</p><el-alert v-if="data.payoutProfile" type="success" :closable="false" :title="`${payoutMethod(data.payoutProfile.method)} · ${data.payoutProfile.accountMasked} · ${data.payoutProfile.realNameMasked}`" /><el-form label-position="top"><el-form-item label="收款方式"><el-select v-model="payout.method"><el-option label="支付宝" value="alipay" /><el-option label="微信支付" value="wxpay" /><el-option label="银行卡" value="bank" /></el-select></el-form-item><el-form-item label="收款账号"><el-input v-model="payout.account" autocomplete="off" /></el-form-item><el-form-item label="真实姓名"><el-input v-model="payout.realName" autocomplete="off" /></el-form-item><el-button type="primary" :loading="savingPayout" @click="savePayout">加密保存</el-button></el-form></div></el-tab-pane>
    </el-tabs>

    <el-dialog v-model="payOpen" title="选择支付方式" width="430px"><el-radio-group v-model="payType" class="pay-types"><el-radio-button v-for="type in payTypes" :key="type" :value="type">{{ payTypeLabel(type) }}</el-radio-button></el-radio-group><el-alert type="info" :closable="false" title="将使用后台已有易支付配置跳转付款，支付结果以异步验签回调为准。" /><template #footer><el-button @click="payOpen=false">取消</el-button><el-button type="primary" :loading="actingId===selectedOrder?.id" @click="pay">前往支付</el-button></template></el-dialog>
    <el-dialog v-model="meetupOpen" title="交付安排" width="460px"><el-form label-position="top"><el-form-item label="交付时间"><el-date-picker v-model="meetup.time" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss.SSSZ" style="width:100%" /></el-form-item><el-form-item label="交付地点"><el-input v-model="meetup.location" maxlength="120" /></el-form-item><el-form-item label="备注"><el-input v-model="meetup.note" type="textarea" :rows="3" maxlength="500" /></el-form-item></el-form><template #footer><el-button @click="meetupOpen=false">取消</el-button><el-button type="primary" @click="saveMeetup">保存</el-button></template></el-dialog>
    <el-dialog v-model="refundOpen" title="申请退款" width="440px"><el-input v-model="refundReason" type="textarea" :rows="4" maxlength="500" show-word-limit placeholder="说明退款原因" /><template #footer><el-button @click="refundOpen=false">取消</el-button><el-button type="danger" @click="requestRefund">提交退款申请</el-button></template></el-dialog>
    <el-dialog v-model="reviewOpen" title="评价交易" width="440px"><div class="review-box"><el-rate v-model="review.rating" /><el-input v-model="review.content" type="textarea" :rows="4" maxlength="500" show-word-limit placeholder="分享本次交易体验" /></div><template #footer><el-button @click="reviewOpen=false">取消</el-button><el-button type="primary" @click="submitReview">提交评价</el-button></template></el-dialog>
  </div>
</template>

<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { ElMessage,ElMessageBox } from 'element-plus';import { marketApi,submitMarketEpay,type MarketItem,type MarketOrder } from '@/api/market';import type { PayType } from '@/api/payments';import { useAuthStore } from '@/stores/auth';import { fmtRelative } from '@/utils/format';
const route=useRoute(),router=useRouter(),auth=useAuthStore();const tab=ref(String(route.query.tab||'selling')),sellingStatus=ref('all'),loading=ref(false),actingId=ref(0);const data=reactive<any>({selling:[],favorites:[],offers:[],orders:[],conversationCount:0,payoutProfile:null});
const sellingOptions=[{label:'全部',value:'all'},{label:'进行中',value:'active'},{label:'预订/洽谈',value:'reserved'},{label:'已成交/求到',value:'sold'},{label:'草稿/已结束',value:'inactive'}];const filteredSelling=computed(()=>data.selling.filter((item:MarketItem)=>sellingStatus.value==='all'||(sellingStatus.value==='inactive'?['draft','withdrawn','hidden','reviewing'].includes(item.status):item.status===sellingStatus.value)));const buyerOffers=computed(()=>data.offers);const sellerOffers=computed(()=>data.sellerOffers||[]);
const payOpen=ref(false),meetupOpen=ref(false),refundOpen=ref(false),reviewOpen=ref(false),selectedOrder=ref<MarketOrder|null>(null);const payTypes=ref<PayType[]>([]),payType=ref<PayType>('alipay');const meetup=reactive({time:'',location:'',note:''}),refundReason=ref(''),review=reactive({rating:5,content:''});const payout=reactive({method:'alipay' as 'alipay'|'wxpay'|'bank',account:'',realName:''}),savingPayout=ref(false);
onMounted(load);function syncTab(){router.replace({query:{...route.query,tab:tab.value}})}
async function load(){loading.value=true;try{const [mine,meta]=await Promise.all([marketApi.mine({suppressErrorMessage:true}),marketApi.meta({suppressErrorMessage:true})]);Object.assign(data,mine);payTypes.value=meta.payTypes;if(payTypes.value.length&&!payTypes.value.includes(payType.value))payType.value=payTypes.value[0];}catch(e){ElMessage.error(e instanceof Error?e.message:'数据加载失败');}finally{loading.value=false;}}
// Seller-facing offers are returned through the order/offer stream after acceptance; pending offers are loaded from item detail in a compact fallback.
async function handleOffer(offer:any,action:'accept'|'reject'|'cancel'){actingId.value=offer.id;try{await marketApi.updateOffer(offer.id,action);ElMessage.success(action==='accept'?'已接受，等待买家支付':'操作成功');await load();}finally{actingId.value=0;}}
function openPay(order:MarketOrder){selectedOrder.value=order;payOpen.value=true}async function pay(){if(!selectedOrder.value)return;if(!payTypes.value.length)return ElMessage.warning('后台尚未启用易支付渠道');actingId.value=selectedOrder.value.id;try{const result=await marketApi.payOrder(selectedOrder.value.id,payType.value);submitMarketEpay(result);}finally{actingId.value=0;}}
function openMeetup(order:MarketOrder){selectedOrder.value=order;meetup.time=order.meetupTime||'';meetup.location=order.meetupLocation||'';meetup.note='';meetupOpen.value=true}async function saveMeetup(){if(!selectedOrder.value)return;await marketApi.updateOrder(selectedOrder.value.id,{action:'set_meetup',meetupTime:meetup.time||undefined,meetupLocation:meetup.location,note:meetup.note});meetupOpen.value=false;ElMessage.success('交付安排已更新');await load();}
async function orderAction(order:MarketOrder,action:string){await ElMessageBox.confirm(order.deliveryType==='digital'?'请确认电子资料可以正常打开或下载。':'请确认商品已经完成实际交付。','确认交易',{type:'warning'});await marketApi.updateOrder(order.id,{action});ElMessage.success('确认成功');await load();}
function openRefund(order:MarketOrder){selectedOrder.value=order;refundReason.value='';refundOpen.value=true}async function requestRefund(){if(!selectedOrder.value||!refundReason.value.trim())return ElMessage.warning('请填写退款原因');await marketApi.updateOrder(selectedOrder.value.id,{action:'request_refund',reason:refundReason.value});refundOpen.value=false;ElMessage.success('退款申请已提交');await load();}
function hasReviewed(order:any){return Array.isArray(order.reviews)&&order.reviews.some((r:any)=>r.authorId===auth.user?.id)}function openReview(order:MarketOrder){selectedOrder.value=order;review.rating=5;review.content='';reviewOpen.value=true}async function submitReview(){if(!selectedOrder.value)return;await marketApi.reviewOrder(selectedOrder.value.id,review);reviewOpen.value=false;ElMessage.success('评价已提交');await load();}
async function savePayout(){if(!payout.account.trim()||!payout.realName.trim())return ElMessage.warning('请填写完整收款资料');savingPayout.value=true;try{data.payoutProfile=await marketApi.savePayoutProfile(payout);payout.account='';payout.realName='';ElMessage.success('收款资料已加密保存');}finally{savingPayout.value=false;}}
function itemStatus(item:MarketItem){if(item.listingType==='wanted')return({active:'求购中',reserved:'洽谈中',sold:'已求到',draft:'草稿',reviewing:'审核中',withdrawn:'已结束',hidden:'已隐藏'} as any)[item.status]||item.status;return({active:'在售',reserved:'已预订',sold:'已售出',draft:'草稿',reviewing:'审核中',withdrawn:'已下架',hidden:'已隐藏'} as any)[item.status]||item.status}function offerStatus(v:string){return({pending:'等待卖家',accepted:'已接受',rejected:'未接受',cancelled:'已撤回',expired:'已过期'} as any)[v]||v}function orderStatus(v:string){return({pending_payment:'待支付',paid:'已支付',delivering:'交付中',completed:'已完成',cancelled:'已取消',refund_pending:'退款处理中',refunded:'已退款',disputed:'纠纷处理中'} as any)[v]||v}function payTypeLabel(v:string){return({alipay:'支付宝',wxpay:'微信支付',qqpay:'QQ 钱包',bank:'网银',jdpay:'京东支付'} as any)[v]||v}function payoutMethod(v:string){return({alipay:'支付宝',wxpay:'微信支付',bank:'银行卡'} as any)[v]||v}function formatTime(v:string){return new Date(v).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})}
</script>

<style scoped>
.mine-page{display:flex;flex-direction:column;gap:18px}.page-head{display:flex;align-items:flex-end;justify-content:space-between;gap:18px}.page-head span{color:var(--cpu-primary);font-size:11px;letter-spacing:.13em}.page-head h1{margin:5px 0;font-size:27px}.page-head p{margin:0;color:var(--cpu-text-secondary);font-size:12px}.market-tabs{padding:10px 18px 20px}.section-tools{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}.listing-list,.offer-list,.order-list{display:flex;flex-direction:column;gap:10px}.listing-list article,.offer-list article{display:flex;align-items:center;gap:13px;padding:12px;border:1px solid var(--cpu-border-soft);border-radius:11px}.item-cover{width:75px;height:68px;display:grid;place-items:center;overflow:hidden;border-radius:8px;background:var(--cpu-surface-soft);font-size:26px}.item-cover img{width:100%;height:100%;object-fit:cover}.item-main,.offer-list article>div:first-child{min-width:0;flex:1}.item-main>div{display:flex;gap:8px}.item-main strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.item-main em{padding:2px 5px;border-radius:4px;color:#0f766e;background:#ecfdf5;font-size:9px;font-style:normal}.item-main p,.offer-list p{margin:5px 0;font-size:12px}.item-main small,.offer-list small{color:var(--cpu-text-secondary)}.item-actions,.offer-list article>div:last-child{display:flex;gap:5px}.offer-list h3{margin:15px 0 4px}.offer-list b{color:#ef4444}.order-card{overflow:hidden;border:1px solid var(--cpu-border-soft);border-radius:12px}.order-card header{display:flex;justify-content:space-between;padding:9px 12px;color:var(--cpu-text-secondary);background:var(--cpu-surface-soft);font-size:10px}.order-card header em{color:#0f766e;font-style:normal}.order-body{display:flex;gap:12px;padding:13px}.order-copy{display:flex;flex-direction:column;gap:5px}.order-copy p{margin:0;font-size:12px}.order-copy b{color:#ef4444}.order-copy small{color:var(--cpu-text-secondary);font-size:10px}.order-card footer{display:flex;justify-content:flex-end;gap:5px;padding:9px 12px;border-top:1px solid var(--cpu-border-soft);flex-wrap:wrap}.favorite-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:10px}.favorite-grid article{display:flex;flex-direction:column;gap:6px;padding:9px;border:1px solid var(--cpu-border-soft);border-radius:10px;cursor:pointer}.favorite-grid article>div{height:120px;display:grid;place-items:center;overflow:hidden;border-radius:7px;background:var(--cpu-surface-soft);font-size:32px}.favorite-grid img{width:100%;height:100%;object-fit:cover}.favorite-grid strong{height:34px;overflow:hidden;font-size:11px}.favorite-grid b{color:#ef4444}.payout-card{max-width:560px}.payout-card h2{margin-top:0}.payout-card>p{color:var(--cpu-text-secondary);font-size:12px;line-height:1.7}.payout-card .el-alert{margin:13px 0}.pay-types{display:flex;margin-bottom:14px}.review-box{display:flex;flex-direction:column;gap:14px}@media(max-width:800px){.page-head{align-items:flex-start;flex-direction:column}.favorite-grid{grid-template-columns:repeat(2,1fr)}.listing-list article,.offer-list article{align-items:flex-start;flex-wrap:wrap}.item-actions,.offer-list article>div:last-child{width:100%;justify-content:flex-end}.market-tabs{padding:8px 10px 16px}}
.digital-delivery{margin:0 13px 12px;padding:13px;border:1px solid #b7e4d9;border-radius:10px;background:#f0fdfa}.digital-delivery b{color:#0f766e;font-size:12px}.digital-delivery pre{margin:9px 0;padding:10px;border-radius:8px;background:#fff;white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.7 ui-monospace,SFMono-Regular,Consolas,monospace}.digital-delivery small{color:var(--cpu-text-secondary)}
.item-main em,.order-card header em{color:var(--cpu-primary);background:var(--cpu-primary-soft)}.digital-delivery{border-color:var(--cpu-border-soft);background:var(--cpu-primary-soft)}.digital-delivery b{color:var(--cpu-primary)}.digital-delivery pre{color:var(--cpu-text);background:var(--cpu-card);border:1px solid var(--cpu-border-soft)}
</style>
